/* Illustrative sample album; no real school photos. */
window.EduvizeGalleryDemo=async function(){
 const img=new Image();img.src='data:image/jpeg;base64,';await img.decode();const items=[];
 const titles=['Cesta do lesa','Podzimní barvy','Výhled do údolí','Přes lesní lávku','U rybníka','Hradní nádvoří'];
 for(let i=0;i<6;i++){const portrait=i===1||i===3,c=document.createElement('canvas');c.width=portrait?300:600;c.height=450;const sw=img.width/3,sh=img.height/2,sx=(i%3)*sw,sy=Math.floor(i/3)*sh,actual=portrait?sh*2/3:sw;c.getContext('2d').drawImage(img,sx+(sw-actual)/2,sy,actual,sh,0,0,c.width,c.height);items.push({id:'demo-'+i,name:titles[i],width:c.width,height:c.height,mime:'image/jpeg',src:c.toDataURL('image/jpeg',.8),date:'2026-10-22T10:00:00Z'});}
 return {id:'demo-album',local:true,name:'Podzimní výlet · ukázka',items,settings:{...EduvizeGallery.defaults},demo:true};
};
